#include "cache.hpp"
#include <cstdio>
#include <cstring>
#include <string>
#include <chrono>
using namespace halo6000;
static std::string quote(const std::string&s){std::string o="\"";for(unsigned char c:s){if(c=='"'||c=='\\'){o+='\\';o+=char(c);}else if(c<32){char t[7];snprintf(t,sizeof(t),"\\u%04x",c);o+=t;}else o+=char(c);}return o+'"';}
static int fail(const Error&e){fprintf(stderr,"halo6000: %s\n",e.message.c_str());return 1;}
int main(int argc,char**argv){if(argc<3){fprintf(stderr,"usage: inspect inspect SOURCE [--list]\n       inspect repack SOURCE CACHE_DIR [--verify] [--list]\n       inspect check SOURCE CACHE_DIR [--list]\n");return 2;}std::string cmd=argv[1],source=argv[2];bool list=false,verify=cmd=="check";for(int i=3;i<argc;i++){list|=strcmp(argv[i],"--list")==0;verify|=strcmp(argv[i],"--verify")==0;}
 auto started=std::chrono::steady_clock::now();auto gg=Gguf::open(source);if(!gg.ok())return fail(gg.error());auto valid=gg.value().validate_model();if(!valid.ok())return fail(valid.error());uint64_t srcbytes=0,cachedbytes=0;size_t pane=0,q8=0,q2k=0,f32=0;
 if(cmd=="inspect"){for(auto&t:gg.value().tensors){srcbytes+=t.bytes;if(t.type==143){cachedbytes+=pane_bytes(t.elements()/128);pane++;}else if(t.type==8){cachedbytes+=t.elements()/128*136;q8++;}else if(t.type==10){cachedbytes+=t.bytes;q2k++;}else{cachedbytes+=t.elements()*4;f32++;}}printf("{\"source\":%s,\"geometry_valid\":true,\"tensors\":%zu,\"source_tensor_bytes\":%llu,\"cache_tensor_bytes\":%llu,\"pane\":%zu,\"q8\":%zu,\"q2k\":%zu,\"f32\":%zu",quote(source).c_str(),gg.value().tensors.size(),(unsigned long long)srcbytes,(unsigned long long)cachedbytes,pane,q8,q2k,f32);if(list){printf(",\"tensor_table\":[");int n=0;for(auto&t:gg.value().tensors){printf("%s{\"name\":%s,\"type\":%u,\"bytes\":%zu,\"shape\":[",n++?",":"",quote(t.name).c_str(),t.type,t.bytes);for(size_t j=0;j<t.shape.size();j++)printf("%s%llu",j?",":"",(unsigned long long)t.shape[j]);printf("]}");}printf("]");}printf("}\n");return 0;}
 if((cmd!="repack"&&cmd!="check")||argc<4)return 2;auto image=load_cached(source,argv[3],cmd=="repack",true);if(!image.ok())return fail(image.error());if(verify){auto checked=verify_image(gg.value(),image.value());if(!checked.ok())return fail(checked.error());}
 for(auto&t:image.value().tensors)cachedbytes+=t.bytes;double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count();printf("{\"source\":%s,\"cache\":%s,\"cache_version\":%u,\"geometry_valid\":true,\"payload_checksums_valid\":true,\"source_weights_verified\":%s,\"tensors\":%zu,\"cache_tensor_bytes\":%llu,\"cache_file_bytes\":%zu,\"seconds\":%.3f",quote(source).c_str(),quote(image.value().provenance.cache_path).c_str(),CacheVersion,verify?"true":"false",image.value().tensors.size(),(unsigned long long)cachedbytes,image.value().storage->size,seconds);
 if(list){printf(",\"tensor_table\":[");int n=0;for(auto&t:image.value().tensors){auto v=t.view();printf("%s{\"name\":%s,\"format\":%u,\"source_type\":%u,\"bytes\":%zu,\"n\":%d,\"k\":%d,\"experts\":%d,\"row_stride\":%llu,\"expert_stride\":%llu}",n++?",":"",quote(t.name).c_str(),uint32_t(t.format),t.source_type,t.bytes,v.n,v.k,v.experts,(unsigned long long)v.row_stride,(unsigned long long)v.expert_stride);}printf("]");}printf("}\n");return 0;
}
